async function api(path, value) { const response = await fetch('/api/'+path, {method:value===undefined?'GET':'POST',headers:{'X-Memorive-Console':'1',...(value===undefined?{}:{'Content-Type':'application/json'})},...(value===undefined?{}:{body:JSON.stringify(value)})});const result=await response.json();if(!response.ok)throw new Error(errors[result.error_code]||result.error_code||tr("请求失败"));return result; }
let noticeTimer;
function notice(text,error=false){clearTimeout(noticeTimer);const node=$('#notice');node.textContent=text;node.hidden=false;node.classList.toggle('error',error);if(!error)noticeTimer=setTimeout(()=>{node.hidden=true;},6500);}
