function capabilities(){const all=Object.keys(catalog?.operations||{}),connected=observedOnline&&['CONNECTED','WAITING_FOR_ACCESS','REFERENCE_ONLY'].includes(snapshot?.state),declared=connected?all.filter(id=>snapshot.supported_operations?.includes(id)):[],business=Boolean(snapshot?.business_operations_enabled),supported=declared.filter(id=>business||['diagnostics','expression.cancel'].includes(id)),missing=all.filter(id=>!declared.includes(id)),gated=declared.filter(id=>!supported.includes(id));return {all,connected,declared,supported,missing,gated,business,diagnosticsOnly:supported.length===1&&supported[0]==='diagnostics'};}
