function suiteSessionView(suite,value){const active=value?.session?.session_id||null,health=value?.connection_monitor?.health;if(suite?.session_id!==active)return {live:false,suffix:tr(" · 历史结果（其他会话）")};if(!['CONNECTED','REFERENCE_ONLY'].includes(value?.state)||['DISCONNECTED','RECOVERING'].includes(health))return {live:false,suffix:tr(" · 历史结果（会话未确认）")};if(health!=='STABLE')return {live:false,suffix:tr(" · 结果保留（会话待确认）")};return {live:true,suffix:''};}
