function connectedNotice(value){if(value.state==='WAITING_FOR_ACCESS')return tr("Memorive 已连接；请在临时实例中开启「允许接入控制台」。");const count=value.supported_operations?.length||0,preset=value.suite_catalog?.find(row=>row.preset_id==='full_safe');if(!count)return tr("版本已连接，暂无可用测试操作。");if(count===1&&value.supported_operations[0]==='diagnostics')return tr("版本已连接 · 仅诊断可用。");return tr("${0} 已连接 · ${1} 项操作 · 接口回归 ${2}/${3}。",releaseLabel(value.session?.build),count,preset?.available_case_count||0,preset?.case_count||29);}
function connectionView(value,info){const monitor=value.connection_monitor||{},health=monitor.health,projection=value.native_projection_monitor||{};if(value.state==='WAITING_FOR_ACCESS')return {text:names.WAITING_FOR_ACCESS,className:'badge limited'};if(health==='DEGRADED'&&['CONNECTED','REFERENCE_ONLY'].includes(value.state))return {text:tr("连接待确认"),className:'badge degraded'};if(health==='RECOVERING'&&value.state==='DISCONNECTED')return {text:tr("正在恢复连接 · ${0}/${1}",monitor.consecutive_successes||0,monitor.recovery_success_threshold||2),className:'badge degraded'};if(projection.health==='STALE'&&['CONNECTED','REFERENCE_ONLY'].includes(value.state))return {text:tr("会话在线 · 数据刷新异常"),className:'badge degraded'};if(value.state==='CONNECTED'){const text=info.diagnosticsOnly?tr("已连接 · 仅诊断可用"):!info.supported.length?tr("已连接 · 未开放操作"):info.missing.length?tr("已连接 · ${0} 项操作可用",info.supported.length):names.CONNECTED;return {text,className:'badge '+(info.missing.length?'limited':'live')};}if(value.state==='REFERENCE_ONLY')return {text:names.REFERENCE_ONLY,className:'badge reference'};return {text:names[value.state]||value.state,className:'badge'+(['DISCONNECTED','CLEANUP_FAILED'].includes(value.state)?' failed':'')};}
function syncCapabilities(){if(!catalog)return;const info=capabilities(),session=snapshot?.session?.session_id||null;const signature=JSON.stringify([session,info.connected,info.supported,info.gated,info.missing]);if(signature===capabilitySignature)return;capabilitySignature=signature;const select=$('#operation'),previous=select.value;select.replaceChildren();for(const [title,ids,enabled,suffix] of [[tr("当前可用"),info.supported,true,''],[tr("等待控制台许可"),info.gated,false,tr(" · 许可关闭")],[info.connected?tr("当前版本待接入"):tr("连接 Memorive 后检查"),info.missing,false,tr(" · 未接入")]]){if(!ids.length)continue;const group=document.createElement('optgroup');group.label=title;for(const id of ids){const row=option(id,tr(catalog.operations[id].title)+(enabled?'':suffix));row.disabled=!enabled;group.append(row);}select.append(group);}select.value=info.supported.includes(previous)?previous:info.supported[0]||'';renderFields();$('#capability-list').replaceChildren();for(const id of [...info.supported,...info.gated,...info.missing]){const row=document.createElement('span');row.className='capability-item'+(info.supported.includes(id)?' available':'');row.textContent=tr(catalog.operations[id].title)+' · '+(info.supported.includes(id)?tr("可用"):info.gated.includes(id)?tr("许可关闭"):info.connected?tr("版本待接入"):tr("待连接"));$('#capability-list').append(row);}}
function syncSuiteCatalog(){
 const presets=suitePresets(),signature=JSON.stringify(presets.map(row=>[row.preset_id,row.status,row.available_case_count,row.case_count]));
 if(signature===suiteCatalogSignature)return;
 suiteCatalogSignature=signature;
 const select=$('#suite-preset'),previous=select.value;select.replaceChildren();
 for(const preset of presets){const availability=preset.status==='READY'?tr("${0} 项",preset.case_count):tr("${0}/${1} 项",preset.available_case_count,preset.case_count);select.append(option(preset.preset_id,`${tr(preset.title)} · ${availability}`));}
 select.value=presets.some(row=>row.preset_id===previous)?previous:(presets.find(row=>row.recommended)||presets[0])?.preset_id||'';
 renderSuite();
}
function renderSuite(){
 const suite=visibleSuite(),preset=selectedPreset(),panel=$('.suite-panel');
 $('#suite-description').textContent=preset?`${tr(preset.description)} · ${preset.status==='PARTIAL'?tr("缺失能力会记为跳过"):tr("零模型调用")}`:tr("连接 Memorive 后运行整套安全回归");
 $('#suite-ready-count').textContent=String(preset?.available_case_count||0);$('#suite-missing-count').textContent=String(Math.max(0,(preset?.case_count||0)-(preset?.available_case_count||0)));
 if(!suite){
  $('#suite-state').textContent=tr("待运行");$('#suite-current').textContent=preset?.status==='PARTIAL'?tr("${0} 项能力未接入",preset.missing_operations.length):'—';
  $('#suite-progress-fill').style.width='0%';$('#suite-progress-text').textContent=`0 / ${preset?.case_count||0}`;
  $('#suite-pass').textContent='0';$('#suite-fail').textContent='0';$('#suite-skip').textContent='0';$('#review-bundle').hidden=true;
  panel.classList.remove('running','passed','failed');return;
 }
 const progress=suite.progress||{completed:0,total:suite.summary?.total||0,current_case_id:null},percent=progress.total?Math.round(progress.completed/progress.total*100):0,sessionView=suiteSessionView(suite,snapshot);
 const stateNames={QUEUED:tr("排队中"),RUNNING:tr("运行中"),CANCEL_REQUESTED:tr("正在停止"),COMPLETED:suite.verdict==='PASS'?tr("回归通过"):tr("发现问题"),CANCELLED:tr("已停止")};
 $('#suite-state').textContent=(stateNames[suite.state]||suite.state)+(['COMPLETED','CANCELLED'].includes(suite.state)?sessionView.suffix:'');
 $('#suite-current').textContent=progress.current_case_id||suite.completed_at?.replace('T',' ').replace('Z',' UTC')||'—';
 $('#suite-progress-fill').style.width=percent+'%';$('.progress-track').setAttribute('aria-valuenow',String(percent));
 $('#suite-progress-text').textContent=`${progress.completed} / ${progress.total}`;
 $('#suite-pass').textContent=suite.summary?.passed||0;$('#suite-fail').textContent=suite.summary?.failed||0;$('#suite-skip').textContent=suite.summary?.skipped||0;
 panel.classList.toggle('running',['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(suite.state));panel.classList.toggle('passed',suite.verdict==='PASS'&&sessionView.live);panel.classList.toggle('failed',suite.verdict==='FAIL');panel.classList.toggle('historical',['COMPLETED','CANCELLED'].includes(suite.state)&&!sessionView.live);
 const bundle=suite.review_bundle||snapshot?.latest_review_bundle;$('#review-bundle').hidden=!bundle;
 if(bundle)$('#review-path').textContent=bundle.json_path;
}
function nativePreviewStyle(sample,size=180){const assets={idle:'one_eye','blink-open':'neutral','blink-closed':'sleepy',interaction:'wink',working:'shovel',success:'writing','save-success':'success',error:'injury'},value=sample?.transform;if(!Array.isArray(value)||value.length!==6)return null;const [frame,x,y,rotation,scale,opacity]=value,ratio=size/90,numbers=[x,y,rotation,scale,opacity].map(Number);if(!assets[frame]||numbers.some(item=>!Number.isFinite(item)))return null;return {asset:assets[frame],transform:`translate(${numbers[0]*ratio}px, ${numbers[1]*ratio}px) rotate(${numbers[2]}deg) scale(${numbers[3]})`,opacity:String(numbers[4])};}
function expressionEvents(){return Array.isArray(snapshot?.expression_catalog?.events)?snapshot.expression_catalog.events:[];}
function expressionEvent(){return expressionEvents().find(row=>row.event_id===selectedExpressionId)||null;}
function expressionAsset(event,sample){if(sample?.current_asset)return sample.current_asset;if(sample?.frame)return nativePreviewStyle(sample,90)?.asset||null;if(event?.asset)return event.asset;const id=event?.event_id||'',name=id.split('.').slice(1).join('.'),fallback={idle:'one_eye',drag:'one_eye',sleep:'sleepy',blink:'neutral',interaction:'wink',wake:'one_eye',message:'one_eye',working:'shovel',attention:'question',success:'writing','save-success':'success',error:'injury'};return fallback[name]||null;}
