function rows(){if(!snapshot)return;const values=activeTab==='suites'?snapshot.suites||[]:activeTab==='commands'?snapshot.commands:activeTab==='events'?snapshot.events:snapshot.native?.[activeTab]||[];$('#records').replaceChildren();if(!values.length){const empty=document.createElement('p');empty.className='empty-state';empty.textContent=tr("此分类暂无记录");$('#records').append(empty);return;}for(const row of [...values].reverse()){const button=document.createElement('button');button.className='record';const title=document.createElement('strong'),meta=document.createElement('small'),state=document.createElement('span');title.textContent=(activeTab==='suites'?tr(row.title):row.title)||row.question||tr(catalog?.operations[row.operation]?.title||'')||row.event_type||row.name||row.job_id||row.command_id||row.qa_id||tr("记录");const stamp=row.completed_at||row.occurred_at||row.created_at||row.updated_at||'',source=(row.reference_only||snapshot?.reference_only)?tr("参考端"):'Memorive';meta.textContent=[source,stamp&&new Date(stamp).toLocaleTimeString(),row.request_id||row.run_id||row.qa_id].filter(Boolean).join(' · ');state.textContent=row.verdict&&row.verdict!=='NOT_ASSESSED'?row.verdict:row.state||row.control_state||row.kind||row.period||(row.simulated?'SIMULATED':String(row.sequence||''));button.append(title,meta,state);button.addEventListener('click',()=>{$('#record-title').textContent=title.textContent;$('#record-json').textContent=JSON.stringify(row,null,2);$('#record-dialog').showModal();});$('#records').append(button);}}
async function refresh(){
 if(refreshing)return true;refreshing=true;
 try{
  snapshot=await api('snapshot');observedOnline=true;syncCapabilities();syncSuiteCatalog();renderSuite();
  const info=capabilities(),connection=connectionView(snapshot,info);
  $('#connection').textContent=connection.text;$('#connection').className=connection.className;
  $('#session-label').textContent=snapshot.session?releaseLabel(snapshot.session.build):tr("未连接");$('#session-path').textContent=snapshot.session?(snapshot.session.build?.path||snapshot.session.data_root):'—';
  const seed=snapshot.session?.local_profile_seed,seeded=['SEEDED','PARTIAL'].includes(seed?.status),seedText=seeded?tr("本机设置 ${0} 项已载入",seed.copied_file_count):snapshot.reference_only?tr("参考端"):snapshot.session?tr("使用默认设置"):tr("本机设置待载入");
  $('#profile-seed').textContent=seedText;$('#profile-seed').classList.toggle('muted',!seeded);
  $('#session-description').textContent=!snapshot.session?tr("等待版本"):snapshot.state==='WAITING_FOR_ACCESS'?tr("临时会话 · 许可关闭"):snapshot.connection_monitor?.health==='DEGRADED'?tr("会话待确认"):snapshot.connection_monitor?.health==='RECOVERING'?tr("正在恢复"):snapshot.native_projection_monitor?.health==='STALE'?tr("会话在线 · 投影已标记过期"):seeded?tr("临时会话 · 已带入本机设置"):tr("临时会话");
  $('#overview-build').textContent=snapshot.session?releaseLabel(snapshot.session.build):tr("等待版本");
  $('#overview-state').textContent=!snapshot.session?tr("拖入 Memorive.exe 后建立隔离审核会话。"):snapshot.state==='WAITING_FOR_ACCESS'?tr("会话已建立，等待 Memorive 开启控制台许可。"):snapshot.reference_only?tr("正在使用协议参考端。"):tr("当前版本已连接，可开始审核。");
  $('#overview-profile').textContent=seedText;
  const overviewSuite=visibleSuite();$('#overview-suite').textContent=!overviewSuite?tr("尚未运行"):overviewSuite.state==='COMPLETED'?`${overviewSuite.verdict||'NOT_ASSESSED'} · ${overviewSuite.summary?.passed||0}/${overviewSuite.summary?.total||0}`:tr("运行中");
  $('#cleanup-label').textContent=snapshot.state==='CLEANUP_FAILED'?tr("仍有数据待清理"):snapshot.session?tr("关闭后自动清理"):snapshot.last_cleanup?tr("已清理 · 0 项"):tr("无待清理数据");
  $('#cleanup-detail').textContent=snapshot.last_cleanup?snapshot.last_cleanup.status:tr("只保留无正文回执");$('#updated').textContent=new Date(snapshot.observed_at).toLocaleTimeString();
  $('#suite-count').textContent=snapshot.suites?.length||0;$('#command-count').textContent=snapshot.commands?.length||0;$('#message-count').textContent=snapshot.native?.messages?.length||0;$('#report-count').textContent=snapshot.native?.reports?.length||0;$('#research-count').textContent=snapshot.native?.research_qa?.length||0;$('#event-count').textContent=snapshot.events?.length||0;
  const current=snapshot.session?.session_id||null;if(previousSession!==current){selectedCommandId=null;selectedExpressionId=null;eventLabCommandId=null;eventLabScenario=null;expressionCatalogSignature='';eventCatalogSignature='';detail(current?snapshot.state==='WAITING_FOR_ACCESS'?tr("会话已建立；等待用户在 Memorive 中开启控制台许可。"):tr("会话已建立，等待测试。"):visibleSuite()||tr("会话已清空。"));previousSession=current;}
  if(selectedCommandId){const record=snapshot.commands?.find(row=>row.command_id===selectedCommandId);if(record)detail(record);}
  const suite=visibleSuite();if(suite&&['COMPLETED','CANCELLED'].includes(suite.state)&&announcedSuiteId!==suite.suite_id){announcedSuiteId=suite.suite_id;detail(suite);notice(suite.verdict==='PASS'?tr("一键回归通过：${0}/${1}。审核包已生成。",suite.summary.passed,suite.summary.total):tr("一键回归结束：${0} 失败，${1} 跳过。请让 Codex 读取审核包。",suite.summary.failed,suite.summary.skipped),suite.verdict==='FAIL');}
  rows();availability();return true;
 }catch(error){observedOnline=false;$('#connection').textContent=tr("控制台服务未连接");$('#connection').className='badge failed';availability();notice(error.message,true);return false;}finally{refreshing=false;}
}
async function loadCatalog(){catalog=await api('catalog');$('#builds').replaceChildren();for(const [i,release]of catalog.builds.entries())$('#builds').append(option(String(i),releaseLabel(release)+(i===0?tr(" · 相邻版本"):'')+(release.bridge_declared?tr(" · 接口就绪"):tr(" · 等待接入"))));if(!catalog.builds.length)$('#builds').append(option('',tr("拖入或选择 Memorive.exe")));$('#operation').replaceChildren();for(const [id,op]of Object.entries(catalog.operations))$('#operation').append(option(id,op.title));chooseBuild();renderFields();renderEventLab();}
function chooseBuild(){const selected=catalog.builds[Number($('#builds').value)];if(selected){$('#build-path').value=selected.path;$('#build-note').textContent=selected.bridge_declared?tr("${0} · 身份与接口已声明",releaseLabel(selected)):tr("${0} · 测试接口待接入",releaseLabel(selected));}availability();}
async function waitForExpressionRestored(probeId,timeout=7000){const deadline=Date.now()+timeout;while(Date.now()<deadline){snapshot=await api('snapshot');observedOnline=true;const state=snapshot.expression_state||{},probe=(state.history||[]).find(row=>row.probe_id===probeId);renderExpression();if(probe&&['COMPLETED','CANCELLED','FAILED'].includes(probe.state)){if(probe.restored!==true)throw new Error(probe.error_code||'EXPRESSION_RESTORE_FAILED');return probe;}await new Promise(resolve=>setTimeout(resolve,100));}throw new Error('EXPRESSION_RESTORE_TIMEOUT');}
$('#builds').addEventListener('change',chooseBuild);$('#build-path').addEventListener('input',availability);$('#operation').addEventListener('change',renderFields);$('#suite-preset').addEventListener('change',()=>{renderSuite();availability();});
$('#pick').addEventListener('click',()=>act(async()=>{if(!window.pywebview?.api?.choose_build)throw new Error(tr("浏览器预览中请直接填写路径；桌面控制台可使用文件选择器。"));const path=await window.pywebview.api.choose_build();if(path)$('#build-path').value=path;}));
function connectRelease(path,source='manual'){return act(async()=>{if(snapshot?.session)throw new Error(errors.END_CURRENT_SESSION_FIRST);if(source==='drop'&&(await api('snapshot')).session)throw new Error(errors.END_CURRENT_SESSION_FIRST);notice(tr("正在验证 Memorive 版本身份与测试接口…"));const inspected=await api('release/inspect',{executable_path:path});$('#build-path').value=path;$('#builds').querySelector('option[value="dropped"]')?.remove();const selected=catalog.builds.findIndex(release=>release.path.toLowerCase()===path.toLowerCase());if(selected<0)$('#builds').append(option('dropped',tr("${0} · 已拖入",releaseLabel(inspected))));$('#builds').value=selected<0?'dropped':String(selected);$('#build-note').textContent=tr("${0} · ${1} · 身份已验证",releaseLabel(inspected),inspected.channel);if(!inspected.bridge_declared)throw new Error(errors.BUILD_BRIDGE_NOT_IMPLEMENTED);notice(tr("${0} 已验证，正在建立临时会话…",releaseLabel(inspected)));const connected=await api('session/start',{mode:'release',executable_path:path});notice(connectedNotice(connected));});}
$('#connect').addEventListener('click',()=>connectRelease($('#build-path').value));
$('#reference').addEventListener('click',()=>act(async()=>{notice(tr("正在启动协议参考端…"));await api('session/start',{mode:'reference'});notice(tr("协议自测已连接。这里验证指令、状态和清理协议，不代表 Memorive 已实现对应能力。"));}));
$('#check-access').addEventListener('click',()=>act(async()=>{const value=await api('snapshot');if(value.console_access_enabled)notice(tr("控制台许可已开启，业务测试与表情预览已解锁。"));else notice(tr("许可仍为关闭状态；请在当前 memo 实例中开启「允许接入控制台」。"));}));
