$('#submit').addEventListener('click',()=>act(async()=>{const operation=$('#operation').value;if(operation==='task.cancel'&&!confirm(tr("取消当前临时会话中的指定任务？")))return;await submitOperation(operation,parameters(),$('#allow-model').checked);}));
