window.MemoriveBuildConsoleMonitor=Object.freeze({review:()=>api('review'),snapshot:()=>api('snapshot'),suites:()=>api('suites'),commands:()=>api('commands'),events:()=>api('events'),expressions:async()=>{const value=await api('snapshot');return {catalog:value.expression_catalog,state:value.expression_state,monitor:value.expression_monitor};},readSuite:id=>api('suites/'+encodeURIComponent(id)),readCommand:id=>api('commands/'+encodeURIComponent(id))});
window.MemoriveBuildConsoleLifecycle=Object.freeze({
 closingStarted(){busy=true;$('#allow-model').checked=false;availability();notice(tr("正在停止本次测试实例并清理临时数据，完成后窗口将自动关闭…"));},
 closingFailed(failure){busy=false;selectedCommandId=null;availability();const reason={CLEANUP_FILE_IN_USE:tr("文件暂时被占用或无法访问"),EXTERNAL_LINK_CLEANUP_BLOCKED:tr("发现指向测试空间外的目录链接"),REPARSE_POINT_CLEANUP_BLOCKED:tr("发现尚不支持清理的目录链接"),CLEANUP_BUSY:tr("另一项清理正在进行")}[failure.error_code]||failure.error_code;notice(tr("关闭前清理未完成：")+reason+(failure.path?'（'+failure.path+'）':'')+tr("。窗口已保留，可再次关闭窗口重试。"),true);detail({cleanup_failed:failure});void refresh();}
});
function clearDrag(){dragDepth=0;$('#drop-overlay').hidden=true;$('#drop-zone').classList.remove('dragging');}
function showDrag(){const blocked=busy||Boolean(snapshot?.session)||!nativeDropReady;$('#drop-overlay').hidden=false;$('#drop-overlay').classList.toggle('blocked',blocked);$('#drop-title').textContent=busy?tr("正在处理，请稍候"):snapshot?.session?tr("请先结束当前测试会话"):nativeDropReady?tr("松开并验证版本"):tr("请在桌面控制台中拖放");$('#drop-description').textContent=snapshot?.session?tr("当前测试数据会保留，拖放不会切换会话。"):nativeDropReady?tr("仅接受带有效发布身份与测试接口的 Memorive.exe"):tr("也可使用路径输入框或文件选择器。");$('#drop-zone').classList.add('dragging');}
window.MemoriveBuildConsoleDrop=Object.freeze({
 ready(){nativeDropReady=true;availability();},
 unavailable(){nativeDropReady=false;clearDrag();availability();notice(tr("桌面拖放暂不可用，请点击“…”选择 EXE，或直接填写路径。"),true);},
 async accept(payload){clearDrag();if(payload?.error_code){notice(errors[payload.error_code]||tr("无法读取拖入的 EXE。"),true);return;}if(busy){notice(tr("正在处理上一项操作，请稍候再拖入版本。"),true);return;}if(snapshot?.session){notice(errors.END_CURRENT_SESSION_FIRST,true);return;}if(!catalog||!snapshot){notice(tr("控制台正在初始化，请稍候再拖入版本。"),true);return;}if(typeof payload?.path!=='string'||!payload.path){notice(errors.DROP_NATIVE_PATH_REQUIRED,true);return;}await connectRelease(payload.path,'drop');}
});
const hasDraggedFiles=event=>Array.from(event.dataTransfer?.types||[]).includes('Files');
window.addEventListener('dragenter',event=>{event.preventDefault();if(hasDraggedFiles(event)){dragDepth++;showDrag();}},true);
window.addEventListener('dragover',event=>{event.preventDefault();if(hasDraggedFiles(event)){event.dataTransfer.dropEffect=busy||snapshot?.session||!nativeDropReady?'none':'copy';}},true);
window.addEventListener('dragleave',event=>{if(hasDraggedFiles(event)&&--dragDepth<=0)clearDrag();},true);
// Do not stop propagation: pywebview's root handler supplies the native full path.
window.addEventListener('drop',event=>{event.preventDefault();clearDrag();if(hasDraggedFiles(event)&&!nativeDropReady)notice(errors.DROP_NATIVE_PATH_REQUIRED,true);},true);
window.addEventListener('blur',clearDrag);window.addEventListener('keydown',event=>{if(event.key==='Escape')clearDrag();});
